import crypto from 'node:crypto'

export interface ConnectorConfig {
  /** Mailchimp API key (Bearer token) */
  mailchimpApiKey: string
  /** Mailchimp audience/list ID */
  mailchimpListId: string
  /** Mailchimp server prefix (e.g., 'us1', 'us2'), defaults to 'us1' */
  mailchimpServerPrefix?: string
  /** Injected fetch for testing */
  fetch?: typeof fetch
}

export interface StripeWebhookPayload {
  id: string
  object: string
  api_version: string
  created: number
  data: {
    object: {
      id: string
      object: string
      customer: string
      customer_details: {
        email: string
      }
      metadata?: {
        plan?: string
      }
      subscription?: string
      payment_status: string
      status: string
    }
  }
  livemode: boolean
  pending_webhooks: number
  request: {
    id: string
    idempotency_key: string | null
  }
  type: string
}

export interface HandleResult {
  mailchimpMemberId: string
  email: string
  tags: string[]
}

function md5Hash(input: string): string {
  return crypto.createHash('md5').update(input).digest('hex')
}

function getFetch(config: ConnectorConfig): typeof fetch {
  return config.fetch ?? fetch
}

export async function handle(payload: StripeWebhookPayload, config: ConnectorConfig): Promise<HandleResult> {
  const session = payload.data?.object
  if (!session) {
    throw new Error('Missing data.object in Stripe webhook payload')
  }

  const email = session.customer_details?.email
  if (!email) {
    throw new Error('Missing customer_details.email in Stripe webhook payload')
  }

  let plan = session.metadata?.plan
  if (!plan && session.subscription) {
    plan = session.subscription
  }
  if (!plan) {
    throw new Error('Missing plan name (metadata.plan or subscription) in Stripe webhook payload')
  }

  const serverPrefix = config.mailchimpServerPrefix ?? 'us1'
  const url = `https://${serverPrefix}.api.mailchimp.com/3.0/lists/${config.mailchimpListId}/members`

  const body = {
    email_address: email,
    status_if_new: 'subscribed' as const,
    tags: [plan],
  }

  const fetchFn = getFetch(config)
  const response = await fetchFn(url, {
    method: 'POST',
    headers: {
      'Authorization': `Bearer ${config.mailchimpApiKey}`,
      'Content-Type': 'application/json',
    },
    body: JSON.stringify(body),
  })

  if (!response.ok) {
    throw new Error(`Mailchimp API error: ${response.status} ${response.statusText} for POST ${url}`)
  }

  const result = await response.json() as { id: string; email_address: string; tags: Array<{ name: string }> }

  return {
    mailchimpMemberId: result.id,
    email: result.email_address,
    tags: result.tags?.map(t => t.name) ?? [plan],
  }
}

