      ...SOURCE_EXAMPLE,
      data: {
        object: {
          ...SOURCE_EXAMPLE.data.object,
          customer_details: { email: 'customer@example.com' },
          metadata: {},
          subscription: 'sub_pro_yearly',
        },
      },
