      data: {
        object: {
          ...SOURCE_EXAMPLE.data.object,
          customer_details: { email: 'customer@example.com' },
          metadata: {},
          subscription: undefined,
        },
      },
    }

    await expect(handle(payload, baseConfig)).rejects.toThrow('Missing plan name')
  })

